using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using MutationChess.Core;

public static class CardAssetBatchConfig
{
    [MenuItem("Tools/??????????????", false, 1000)]
    public static void Run()
    {
        string[] guids = AssetDatabase.FindAssets("t:CardDataAsset");
        if (guids.Length == 0)
        {
            Debug.LogWarning("[CardBatch] Not found any CardDataAsset");
            return;
        }

        int ok = 0;
        int skip = 0;

        foreach (string guid in guids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            CardDataAsset a = AssetDatabase.LoadAssetAtPath<CardDataAsset>(path);
            if (a == null) { skip++; continue; }

            var cfg = GetConfig(a.cardName);
            if (cfg == null)
            {
                string fn = System.IO.Path.GetFileNameWithoutExtension(path);
                cfg = GetConfig(fn);
            }

            if (cfg != null)
            {
                cfg.Apply(a);
                EditorUtility.SetDirty(a);
                ok++;
            }
            else
            {
                Debug.LogWarning("[CardBatch] No config: " + a.cardName + " | " + path);
                skip++;
            }
        }

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log("[CardBatch] Done! Updated:" + ok + " Skipped:" + skip);
    }

    static CardConfig GetConfig(string name)
    {
        if (string.IsNullOrEmpty(name)) return null;
        s_configs.TryGetValue(name, out var v);
        return v;
    }

    class CardConfig
    {
        public CardType cardType = CardType.Attack;
        public CardRarity rarity = CardRarity.Common;
        public CardFaction faction;
        public int cost, damage, block, magic;
        public string desc = "", artPath = "";
        public string[] effects = { }, inherents = { };
        public CardTag[] tags = { };
        public int blood, frost;
        public bool exhaust, colorless;

        public void Apply(CardDataAsset a)
        {
            a.cardType = cardType;
            a.rarity = rarity;
            a.faction = faction;
            a.cost = cost;
            a.damage = damage;
            a.block = block;
            a.magicNumber = magic;
            a.description = desc;
            a.cardArtPath = artPath;
            a.effectIds = new List<string>(effects);
            a.inherentEffectIds = new List<string>(inherents);
            a.tags = new List<CardTag>(tags);
            a.bloodPerEnergy = blood;
            a.blockPerEnergy = frost;
            a.exhaust = exhaust;
            a.isColorless = colorless;
            a.isFactionLocked = (faction != CardFaction.None);
        }
    }

    static string[] E(params string[] e) => e;
    static CardTag[] T(params CardTag[] t) => t;

